<script setup>
import {ref} from 'vue';
defineProps({reservas:Array,busy:Boolean,online:Boolean});const emit=defineEmits(['edit','delete']);const pending=ref(null);
</script>
<template><div v-if="!reservas.length" class="empty">No hay reservas para mostrar.<small>Crea una celebración o cambia tu búsqueda.</small></div><ul v-else class="reservas"><li v-for="reserva in reservas" :key="reserva.id"><div class="date"><strong>{{reserva.fecha.slice(8)}}</strong><small>{{new Date(reserva.fecha+'T12:00:00').toLocaleDateString('es-EC',{month:'short',year:'numeric'})}}</small></div><div class="details"><h3>{{reserva.cliente}}</h3><p>{{reserva.personas}} invitados · Reserva #{{reserva.id}}</p></div><div class="actions"><button class="light" :disabled="busy||!online" @click="emit('edit',reserva)">Editar<span class="sr"> reserva de {{reserva.cliente}}</span></button><button class="danger" :disabled="busy||!online" @click="pending=reserva">Eliminar<span class="sr"> reserva de {{reserva.cliente}}</span></button></div></li></ul><div v-if="pending" class="confirmation" role="alert"><p>¿Eliminar la reserva de <strong>{{pending.cliente}}</strong> del {{pending.fecha}}?</p><div class="actions"><button class="danger" :disabled="busy||!online" @click="emit('delete',pending.id);pending=null">Sí, eliminar</button><button class="light" @click="pending=null">Conservar reserva</button></div></div></template>
